qt(56,"Среднее количество посетителей кинотеатра в первую неделю","Кинотеатрдың бірінші аптадағы келушілерінің орташа саны","Среднее количество посетителей кинотеатра в субботу и воскресенье первой недели","Кинотеатрдың бірінші аптадағы сенбі және жексенбі келушілерінің орташа саны",F(sum(w1),7),F(w1[5]+w1[6],2),common=dict(C,ru='Количество посетителей кинотеатра по дням (задания 56–58).'+C['ru'],kk='Кинотеатр келушілерінің күндер бойынша саны (56–58-тапсырмалар).'+C['kk']))
qt(57,"Среднее количество посетителей кинотеатра в субботу и воскресенье первой недели","Кинотеатрдың бірінші аптадағы сенбі және жексенбі келушілерінің орташа саны","Среднее количество посетителей кинотеатра в субботу и воскресенье второй недели","Кинотеатрдың екінші аптадағы сенбі және жексенбі келушілерінің орташа саны",F(w1[5]+w1[6],2),F(w2[5]+w2[6],2),common=dict(C))
qt(58,"Модуль разницы количества посетителей в пятницу первой и второй недели","Бірінші және екінші аптадағы жұма күнгі келушілер санының айырмасының модулі","Модуль разницы количества посетителей в среду первой и второй недели","Бірінші және екінші аптадағы сәрсенбі күнгі келушілер санының айырмасының модулі",abs(w1[4]-w2[4]),abs(w1[2]-w2[2]),common=dict(C))
qt(59,"Цена товара 300 тенге, за 1 месяц цена товара выросла до 360 тенге. На сколько процентов выросла цена товара?","Тауар бағасы 300 теңге, 1 айда тауар бағасы 360 теңгеге дейін өсті. Тауар бағасы неше пайызға өсті?","Цена товара 500 тенге, за 1 месяц цена товара выросла до 650 тенге. На сколько процентов выросла цена товара?","Тауар бағасы 500 теңге, 1 айда тауар бағасы 650 теңгеге дейін өсті. Тауар бағасы неше пайызға өсті?",F(360-300,300),F(650-500,500))
